var sv=SugarCube.State.variables, ts=sv.game_state.time_state, out={};
ts.current_day='Monday';
// Cole at 15:00
ts.current_hour=15; ts.current_minute=0;
var cl=setup.getNpcLocation('npc_cole'); out.cole_loc_15=cl&&cl.location;
// Pam at 08:00
ts.current_hour=8;
var pl=setup.getNpcLocation('npc_pam'); out.pam_loc_08=pl&&pl.location;
// resolve expected uuids
var locs=setup.locations||{};
out.park_uuid=(locs['loc_town_park']||{}).id;
out.hallway_uuid=(locs['loc_building_hallway']||{}).id;
// are the new canvases registered at those locations?
var lc=(setup.help_data||{}).locationCanvases||{}, fp=false,fc=false;
for(var k in lc){(lc[k]||[]).forEach(function(c){
  var id=c.id||c.canvasId||'';
  if(id==='ambient_pam_hallway_neutral')fp=true;
  if(id==='ambient_cole_park_sketching')fc=true;
});}
out.pam_canvas_registered=fp; out.cole_canvas_registered=fc;
out.cole_noticed=(sv.player.flags||{}).cole_noticed;
out.hired=(sv.player.flags||{}).hired_at_diner;
return JSON.stringify(out);
